<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { FormInstance, FormRules } from 'element-plus'
import { ElMessage, ElRadioButton, ElRadioGroup } from 'element-plus'
import { useActorStore } from '../../../app/stores/actor'
import { useOverlayStore } from '../../../app/stores/overlays'
import KnowledgeProgression from '../../../components/data-display/KnowledgeProgression.vue'
import { integrationsApi } from '../api/integrationsApi'
import { flowDirectionLabels, integrationTypeLabels, integrationTypes, type IntegrationDetailResponse, type IntegrationType } from '../api/integrationContracts'
type EditableContractField = { order:number; fieldName:string; dataType:string|null; required:boolean; description:string|null; sampleValue:string|null }
const props=defineProps<{integrationId:number|null}>();const actors=useActorStore();const overlays=useOverlayStore();const detail=ref<IntegrationDetailResponse|null>(null);const loading=ref(true);const saving=ref(false);const error=ref<string|null>(null);const form=reactive({name:'',integrationType:'RabbitMq' as IntegrationType,sourceSystemId:null as number|null,sourcePartyName:'',targetSystemId:null as number|null,targetPartyName:'',flowDirection:'OneWay' as 'OneWay'|'Bidirectional',purpose:'',url:'',method:'',exchange:'',topic:'',queue:'',filePath:'',databaseSourceId:null as number|null,databaseObjectId:null as number|null,fields:[] as EditableContractField[]})
const formRef=ref<FormInstance>();const rules:FormRules<typeof form>={name:[{required:true,message:'请输入集成名称',trigger:'blur'}],sourcePartyName:[{required:true,message:'请输入来源方名称',trigger:'blur'}],targetPartyName:[{required:true,message:'请输入目标方名称',trigger:'blur'}]}
function fill(value:IntegrationDetailResponse){detail.value=value;form.name=value.header.name;form.integrationType=value.header.integrationType;form.sourceSystemId=value.sourceParty.systemId;form.sourcePartyName=value.sourceParty.displayName;form.targetSystemId=value.targetParty.systemId;form.targetPartyName=value.targetParty.displayName;form.flowDirection=value.flowDirection;form.purpose=value.purpose??'';form.url=value.endpoint.url??'';form.method=value.endpoint.method??'';form.exchange=value.endpoint.exchange??'';form.topic=value.endpoint.topic??'';form.queue=value.endpoint.queue??'';form.filePath=value.endpoint.filePath??'';form.databaseSourceId=value.databaseSourceId;form.databaseObjectId=value.databaseObjectId;form.fields=value.contractFields.map(item=>({...item}))}
async function load(){if(!props.integrationId){error.value='集成关系 ID 无效。';return}loading.value=true;try{fill(await integrationsApi.detail(props.integrationId))}catch(caught:unknown){error.value=caught instanceof Error?caught.message:'集成关系加载失败。'}finally{loading.value=false}}
function endpoint():Record<string,string|null>{if(form.integrationType==='HttpApi')return{url:form.url.trim()||null,method:form.method.trim()||null};if(form.integrationType==='RabbitMq')return{exchange:form.exchange.trim()||null,topic:form.topic.trim()||null,queue:form.queue.trim()||null};if(form.integrationType==='FileExchange')return{filePath:form.filePath.trim()||null};return{}}
function addField(){form.fields.push({order:form.fields.length+1,fieldName:'',dataType:null,required:false,description:null,sampleValue:null})}function removeField(index:number){form.fields.splice(index,1);form.fields.forEach((item,order)=>item.order=order+1)}
async function save(){if(!detail.value)return;error.value=null;const valid=await formRef.value?.validate().catch(()=>false);if(!valid)return;if(form.sourceSystemId===null&&form.targetSystemId===null){error.value='来源方或目标方至少一端必须关联已登记系统。';return}saving.value=true;try{const overview={name:form.name.trim(),integrationType:form.integrationType,sourceParty:{systemId:form.sourceSystemId,displayName:form.sourcePartyName.trim()},targetParty:{systemId:form.targetSystemId,displayName:form.targetPartyName.trim()},flowDirection:form.flowDirection,purpose:form.purpose.trim()||null,endpoint:endpoint(),databaseSourceId:form.databaseSourceId,databaseObjectId:form.databaseObjectId,actor:actors.actor,concurrencyToken:detail.value.concurrencyToken};const updated=await integrationsApi.updateOverview(detail.value.id,overview);const fields=form.fields.map((item,order)=>({...item,order:order+1,fieldName:item.fieldName.trim(),dataType:item.dataType?.trim()||null,description:item.description?.trim()||null,sampleValue:item.sampleValue?.trim()||null}));await integrationsApi.replaceContractFields(detail.value.id,{fields,actor:actors.actor,concurrencyToken:updated.concurrencyToken});overlays.closeDrawer();window.dispatchEvent(new CustomEvent('integration:changed'));ElMessage.success('集成关系与契约字段已保存。')}catch(caught:unknown){error.value=caught instanceof Error?caught.message:'保存失败。'}finally{saving.value=false}}
onMounted(()=>void load())
</script>
<template><section class="integration-drawer integration-edit"><header class="skh-drawer-header"><div><small>编辑集成关系</small><h2>{{ detail?.header.name ?? '读取中…' }}</h2><p>{{ detail ? integrationTypeLabels[detail.header.integrationType] : '' }}</p></div><button type="button" aria-label="关闭集成关系编辑" @click="overlays.requestDrawerClose">×</button></header><div v-if="loading" class="integration-drawer__state">正在读取集成关系…</div><template v-else-if="detail"><section class="integration-edit__status"><strong>知识状态</strong><KnowledgeProgression :status="detail.header.knowledgeStatus"/><p>知识状态只能通过明确的状态操作变更。</p></section><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-alert v-if="error" class="authoring-form-alert" type="error" :title="error" :closable="false" show-icon/><el-form-item label="集成名称" prop="name" required><el-input v-model="form.name" class="technical-input"/></el-form-item><el-form-item label="集成类型" required><el-select v-model="form.integrationType"><el-option v-for="type in integrationTypes" :key="type" :value="type" :label="integrationTypeLabels[type]"/></el-select></el-form-item><el-divider content-position="left">参与方与流向</el-divider><el-form-item label="来源方名称" prop="sourcePartyName" required><el-input v-model="form.sourcePartyName"/></el-form-item><el-form-item label="来源系统编号（可选）"><el-input-number v-model="form.sourceSystemId" :min="1" controls-position="right"/></el-form-item><el-form-item label="目标方名称" prop="targetPartyName" required><el-input v-model="form.targetPartyName"/></el-form-item><el-form-item label="目标系统编号（可选）"><el-input-number v-model="form.targetSystemId" :min="1" controls-position="right"/></el-form-item><el-form-item label="数据流向" required><el-radio-group v-model="form.flowDirection"><el-radio-button value="OneWay">{{ flowDirectionLabels.OneWay }}</el-radio-button><el-radio-button value="Bidirectional">{{ flowDirectionLabels.Bidirectional }}</el-radio-button></el-radio-group></el-form-item><el-form-item label="用途"><el-input v-model="form.purpose" type="textarea" :rows="2"/></el-form-item><el-divider content-position="left">技术端点</el-divider><template v-if="form.integrationType==='HttpApi'"><el-form-item label="URL"><el-input v-model="form.url" class="technical-input"/></el-form-item><el-form-item label="HTTP 方法"><el-input v-model="form.method" class="technical-input"/></el-form-item></template><template v-else-if="form.integrationType==='RabbitMq'"><el-form-item label="交换机（Exchange）"><el-input v-model="form.exchange" class="technical-input"/></el-form-item><el-form-item label="主题（Topic）"><el-input v-model="form.topic" class="technical-input"/></el-form-item><el-form-item label="队列（Queue）"><el-input v-model="form.queue" class="technical-input"/></el-form-item></template><template v-else-if="form.integrationType==='FileExchange'"><el-form-item label="文件路径"><el-input v-model="form.filePath" class="technical-input"/></el-form-item></template><template v-else><el-form-item label="数据库来源编号"><el-input-number v-model="form.databaseSourceId" :min="1" controls-position="right"/></el-form-item><el-form-item label="数据库对象编号"><el-input-number v-model="form.databaseObjectId" :min="1" controls-position="right"/></el-form-item></template><el-collapse><el-collapse-item title="消息 / 数据契约字段（低频编辑）" name="fields"><div v-for="(field,index) in form.fields" :key="index" class="integration-field-edit"><el-input v-model="field.fieldName" class="technical-input" placeholder="字段名称"/><el-input v-model="field.dataType" class="technical-input" placeholder="数据类型"/><el-checkbox v-model="field.required">必填</el-checkbox><el-input v-model="field.description" placeholder="说明"/><el-input v-model="field.sampleValue" placeholder="示例值"/><el-button text @click="removeField(index)">移除</el-button></div><el-button text type="primary" @click="addField">+ 添加契约字段</el-button></el-collapse-item></el-collapse></el-form></template><p v-if="error && !detail" class="authoring-error">{{ error }}</p><footer><el-button @click="overlays.requestDrawerClose">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存集成关系</el-button></footer></section></template>
